import re, os, sys, glob
root = sys.argv[1]
files = glob.glob(root+'/docs/**/*.md', recursive=True) + [root+'/README.md'] + glob.glob(root+'/diagrams/*.md')
def slug(h):
    h = h.strip().lower()
    h = re.sub(r'[^\w\- ]', '', h)  # keep word chars, hyphen, space
    return h.replace(' ', '-')
def anchors(path):
    out=set(); counts={}
    try: txt=open(path,encoding='utf-8').read()
    except: return None
    txt=re.sub(r'```.*?```','',txt,flags=re.S)
    for m in re.finditer(r'^#{1,6}\s+(.*)$', txt, re.M):
        s=slug(m.group(1))
        if s in counts: counts[s]+=1; out.add(f"{s}-{counts[s]}")
        else: counts[s]=0; out.add(s)
    return out
bad=0
for f in files:
    txt=open(f,encoding='utf-8').read()
    for m in re.finditer(r'\]\(([^)\s]+)\)', txt):
        link=m.group(1)
        if link.startswith(('http','mailto:')): continue
        p,_,a=link.partition('#')
        target=os.path.normpath(os.path.join(os.path.dirname(f),p)) if p else f
        if not os.path.exists(target):
            print('MISSING', os.path.relpath(f,root), link); bad+=1; continue
        if a and target.endswith('.md'):
            an=anchors(target)
            if a not in an: print('ANCHOR', os.path.relpath(f,root), link); bad+=1
print('bad',bad)
EOF
